/**
 * Converts a given string to title case.
 *
 * @param {string} str - The input string to be converted.
 * @returns {string} The input string in title case.
 */
function toTitleCase(str) {
    // Split the string into words
    const words = str.split(' ');

    // Use array map to capitalize the first letter of each word and make the rest lowercase
    const titleCaseWords = words.map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());

    // Join the words back into a string
    return titleCaseWords.join(' ');
}

