Here's an example of how you could use parameterized queries in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sqlite3.h>

int main() {
    sqlite3* db;
    char* errorMessage;

    // Initialize the SQLite database
    int rc = sqlite3_open("example.db", &db);
    if (rc) {
        fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(db));
        return 1;
    }

    // Create a parameterized query
    const char* query = "SELECT * FROM users WHERE username = ? AND password = ?";

    // Prepare the query
    sqlite3_stmt* stmt;
    rc = sqlite3_prepare_v2(db, query, -1, &stmt, 0);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't prepare statement: %s\n", sqlite3_errmsg(db));
        sqlite3_close(db);
        return 1;
    }

    // Bind the parameters
    rc = sqlite3_bind_text(stmt, 1, "username", -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't bind parameter: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return 1;
    }

    rc = sqlite3_bind_text(stmt, 2, "password", -1, SQLITE_STATIC);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Can't bind parameter: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return 1;
    }

    // Execute the query
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        printf("User found: %s\n", (const char*)sqlite3_column_text(stmt, 0));
    } else {
        printf("User not found\n");
    }

    // Clean up
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}
```

