Here's an algorithm in JavaScript to find the closest pair of points from a given set of points. This algorithm uses the divide-and-conquer approach to achieve a time complexity of O(n log n).

```javascript
class Point {
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }
}

class ClosestPair {
    constructor(points) {
        this.points = points;
    }

    findClosestPair() {
        // Sort the points by their x-coordinates
        this.points.sort((a, b) => a.x - b.x);

        return this._findClosestPair(0, this.points.length - 1);
    }

    _findClosestPair(left, right) {
        if (left >= right) {
            return null;
        }

        const mid = Math.floor((left + right) / 2);
        const leftClosest = this._findClosestPair(left, mid);
        const rightClosest = this._findClosestPair(mid + 1, right);

        const minDistance = Math.min(leftClosest.distance, rightClosest.distance);
        const closestPoints = leftClosest.points.length > rightClosest.points.length ? leftClosest.points : rightClosest.points;

        // Check for points in the middle strip
        for (let i = left; i <= right; i++) {
            for (let j = i + 1; j <= right; j++) {
                const dist = this._distance(this.points[i], this.points[j]);
                if (dist < minDistance) {
                    minDistance = dist;
                    closestPoints.length = 0;
                    closestPoints.push(this.points[i]);
                    closestPoints.push(this.points[j]);
                }
            }
        }

        return { distance: minDistance, points: closestPoints };
    }

    _distance(p1, p2) {
        return Math.sqrt(Math.pow(p1.x - p2.x, 2) + Math.pow(p1.y - p2.y, 2));
    }
}

// Example usage:
const points = [new Point(2, 3), new Point(12, 30), new Point(40, 50), new Point(5, 1), new Point(12, 10), new Point(3, 4)];
const closestPair = new ClosestPair(points);
const result = closestPair.findClosestPair();
console.log(`The closest pair of points is: ${result.points[0].x}, ${result.points[0].y} and ${result.points[1].x}, ${result.points[1].y}`);
console.log(`The distance between the closest pair of points is: ${result.distance}`);
```

This algorithm works by first sorting the points by their x-coordinates. Then, it recursively divides the points into two halves and finds the closest pair of points in each half. The algorithm also checks for points in the middle strip, which are points that are closer to the middle of the strip than to the closest pair found so far. The algorithm returns the closest pair of points and their distance.

