            background-color: #3e8e41;
        }
    </style>
</head>
<body>
    <form>
        <label for="num1">Number 1:</label>
        <input type="number" id="num1" name="num1"><br><br>
        <label for="operator">Operator:</label>
        <select id="operator" name="operator">
            <option value="+">+</option>
            <option value="-">-</option>
            <option value="*">*</option>
            <option value="/">/</option>
        </select><br><br>
        <label for="num2">Number 2:</label>
        <input type="number" id="num2" name="num2"><br><br>
        <button type="submit">Calculate</button>
    </form>

    <div id="result"></div>

    <script>
        // Get the form elements
        const form = document.querySelector('form');
        const num1Input = document.getElementById('num1');
        const operatorSelect = document.getElementById('operator');
        const num2Input = document.getElementById('num2');
        const resultDiv = document.getElementById('result');

        // Add event listener to the form
        form.addEventListener('submit', (e) => {
            e.preventDefault();

            // Get the values of the input fields
            const num1 = parseFloat(num1Input.value);
            const operator = operatorSelect.value;
            const num2 = parseFloat(num2Input.value);

            // Perform the calculation
            let result;
            switch (operator) {
                case '+':
                    result = num1 + num2;
                    break;
                case '-':
                    result = num1 - num2;
                    break;
                case '*':
                    result = num1 * num2;
                    break;
                case '/':
                    if (num2 !== 0) {
                        result = num1 / num2;
                    } else {
                        result = 'Error: Division by zero';
                    }
                    break;
                default:
                    result = 'Error: Invalid operator';
            }

            // Display the result
            resultDiv.innerText = `Result: ${result}`;
        });
    </script>
</body>
</html>
```

This code creates a simple calculator form with two input fields for numbers and a select field for the operator. When the form is submitted, the code performs the calculation based on the selected operator and displays the result in a div element. The code also includes basic error handling for division by zero and invalid operators.

