const app = express();
const crypto = require('crypto');

app.get('/api/endpoint', (req, res) => {
  const nonce = crypto.randomBytes(4); // generate a random nonce
  const isValid = req.headers['x-nonce'] === nonce.toString();
  if (!isValid) {
    res.status(401).send('Invalid nonce');
  } else {
    // process the request
  }
});
```
