VALUES ('SELECT * FROM table1');
```

**Create a stored procedure to validate user input**

Create a stored procedure that takes the user's input query as a parameter. This stored procedure will check if the query is in the allowed queries table.

```sql
CREATE PROCEDURE ValidateQuery
    @Query NVARCHAR(255)
AS
BEGIN
    DECLARE @QueryText NVARCHAR(255) = @Query;
    DECLARE @AllowedQuery NVARCHAR(255);

    SELECT TOP 1 @AllowedQuery = QueryText
    FROM AllowedQueries
    WHERE QueryText LIKE '%' + @Query + '%';

    IF @AllowedQuery IS NULL
    BEGIN
        RAISERROR('Invalid query', 16, 1);
        RETURN;
    END

    -- Execute the allowed query
    EXEC sp_executesql @AllowedQuery;
END
