Here's a simple algorithm in C++ to find the maximum and minimum elements in an unsorted array.

```cpp
#include <iostream>
using namespace std;

// Function to find the maximum element in an array
int findMax(int arr[], int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

// Function to find the minimum element in an array
int findMin(int arr[], int size) {
    int min = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] < min) {
            min = arr[i];
        }
    }
    return min;
}

// Function to find the maximum and minimum elements in an array
void findMaxMin(int arr[], int size) {
    int max = findMax(arr, size);
    int min = findMin(arr, size);
    cout << "Maximum element: " << max << endl;
    cout << "Minimum element: " << min << endl;
}

int main() {
    int arr[] = {12, 45, 7, 23, 56, 89, 34};
    int size = sizeof(arr) / sizeof(arr[0]);
    findMaxMin(arr, size);
    return 0;
}
```

This program defines three functions: `findMax`, `findMin`, and `findMaxMin`. The `findMax` and `findMin` functions take an array and its size as input and return the maximum and minimum elements respectively. The `findMaxMin` function calls these two functions and prints the maximum and minimum elements.

However, this approach has a time complexity of O(n) because it needs to traverse the entire array to find the maximum and minimum elements.

A more efficient approach is to use the `std::max_element` and `std::min_element` functions from the `<algorithm>` library, which have a time complexity of O(n). Here's how you can modify the program to use these functions:

```cpp
#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int arr[] = {12, 45, 7, 23, 56, 89, 34};
    int size = sizeof(arr) / sizeof(arr[0]);
    cout << "Maximum element: " << *max_element(arr, arr + size) << endl;
    cout << "Minimum element: " << *min_element(arr, arr + size) << endl;
    return 0;
}
