Here's an example implementation of a doubly linked list in JavaScript:

```javascript
class Node {
    /**
     * Represents a node in the doubly linked list.
     * @param {any} data - The data stored in the node.
     */
    constructor(data) {
        this.data = data;
        this.next = null;
        this.prev = null;
    }
}

class DoublyLinkedList {
    /**
     * Represents a doubly linked list.
     */
    constructor() {
        this.head = null;
        this.tail = null;
        this.size = 0;
    }

    /**
     * Adds a new node with the given data to the end of the list.
     * @param {any} data - The data to be stored in the new node.
     */
    append(data) {
        const newNode = new Node(data);
        if (!this.head) {
            this.head = newNode;
            this.tail = newNode;
        } else {
            this.tail.next = newNode;
            newNode.prev = this.tail;
            this.tail = newNode;
        }
        this.size++;
    }

    /**
     * Removes the node at the beginning of the list.
     * @returns {any} The data of the removed node.
     */
    shift() {
        if (!this.head) {
            return null;
        }
        const removedNode = this.head;
        if (this.head === this.tail) {
            this.head = null;
            this.tail = null;
        } else {
            this.head = this.head.next;
            this.head.prev = null;
        }
        this.size--;
        return removedNode.data;
    }

    /**
     * Removes the node with the given data from the list.
     * @param {any} data - The data of the node to be removed.
     * @returns {boolean} True if the node was found and removed, false otherwise.
     */
    remove(data) {
        const node = this.find(data);
        if (node) {
            if (node === this.head) {
                this.shift();
            } else if (node === this.tail) {
                this.tail = node.prev;
                this.tail.next = null;
            } else {
                node.prev.next = node.next;
                node.next.prev = node.prev;
            }
            this.size--;
            return true;
        }
        return false;
    }

    /**
     * Finds the node with the given data in the list.
     * @param {any} data - The data of the node to be found.
     * @returns {Node|null} The node with the given data, or null if not found.
     */
    find(data) {
        let currentNode = this.head;
        while (currentNode) {
            if (currentNode.data === data) {
                return currentNode;
            }
            currentNode = currentNode.next;
        }
        return null;
    }

    /**
     * Returns the data of the node at the given index.
     * @param {number} index - The index of the node.
     * @returns {any} The data of the node at the given index.
     */
    get(index) {
        if (index < 0 || index >= this.size) {
            throw new Error("Index out of range");
        }
        let currentNode = this.head;
        for (let i = 0; i < index; i++) {
            currentNode = currentNode.next;
        }
        return currentNode.data;
    }

    /**
     * Returns the size of the list.
     * @returns {number} The size of the list.
     */
    size() {
        return this.size;
    }
}
```

You can use the `DoublyLinkedList` class as follows:

```javascript
