  KeySpec: 'AES_256',
};
kms.createKey(params, (err, data) => {
  if (err) {
    console.log(err);
  } else {
    const keyMaterial = data.KeyMaterial;
    // Store the key material securely
    // ...
  }
});

// Use the key to sign a JWT
