```php
// Generate a unique token
$token = bin2hex(random_bytes(32));

// Store the token in the database
$stmt = $pdo->prepare('INSERT INTO password_reset_tokens (token, email) VALUES (:token, :email)');
$stmt->bindParam(':token', $token);
$stmt->bindParam(':email', $email);
$stmt->execute();

// Send the token to the user's email
$subject = 'Password Reset';
$message = 'Your password reset token is: ' . $token;
mail($email, $subject, $message);

// Check if the token is valid
$stmt = $pdo->prepare('SELECT * FROM password_reset_tokens WHERE token = :token AND email = :email');
$stmt->bindParam(':token', $token);
$stmt->bindParam(':email', $email);
$stmt->execute();
$result = $stmt->fetch();

if ($result) {
    // Token is valid, redirect to password reset page
    header('Location: password_reset.php');
} else {
    // Token is invalid, display error message
    echo 'Invalid token';
}
```

